"""scrcpy 设备控制器 — 基于 adbutils + scrcpy-server 的实现。

通过 scrcpy 协议获取 H264 视频流并解码为截图；触控（click/swipe/long_tap）、
按键和文本输入通过 scrcpy 控制流（INJECT_TOUCH_EVENT / INJECT_KEYCODE /
INJECT_TEXT）实现，延迟远低于 ``adb shell input``。仅应用启停、运行检测等
非实时操作仍走 ADB。

使用方式::

    from autowsgr.emulator.controller import ScrcpyController

    ctrl = ScrcpyController(serial="emulator-5554")
    info = ctrl.connect()
    screen = ctrl.screenshot()
    ctrl.click(0.5, 0.5)
    ctrl.disconnect()
"""

from __future__ import annotations

import socket
import struct
import threading
import time
from pathlib import Path
from typing import TYPE_CHECKING

from autowsgr.infra import DeviceError, EmulatorConfig
from autowsgr.infra.config import operation_delay
from autowsgr.infra.logger import caller_info, get_logger

from ..detector import _find_adb, detect_emulators, prompt_user_select, resolve_serial
from .protocol import AndroidController, DeviceInfo


if TYPE_CHECKING:
    import numpy as np
    from adbutils import AdbConnection, AdbDevice

_log = get_logger('emulator')

# scrcpy-server.jar 打包在 autowsgr/data/bin/ 下
_SCRCPY_SERVER_JAR = Path(__file__).resolve().parents[2] / 'data' / 'bin' / 'scrcpy-server.jar'
_SCRCPY_SERVER_VERSION = '2.7'
_DEVICE_JAR_PATH = '/data/local/tmp/scrcpy-server.jar'

# ── scrcpy 2.7 控制流协议常量 ──
# 参考：scrcpy app/src/control_msg.h / control_msg.c (v2.7)

# 控制消息类型
_TYPE_INJECT_KEYCODE = 0
_TYPE_INJECT_TEXT = 1
_TYPE_INJECT_TOUCH_EVENT = 2
_TYPE_INJECT_SCROLL_EVENT = 3
_TYPE_SET_CLIPBOARD = 9

# SET_CLIPBOARD 文本上限（SC_CONTROL_MSG_CLIPBOARD_TEXT_MAX_LENGTH = 1<<18 - 14）
_CLIPBOARD_TEXT_MAX_LENGTH = (1 << 18) - 14

# Android MotionEvent 动作码
_ACTION_DOWN = 0
_ACTION_UP = 1
_ACTION_MOVE = 2

# Android KeyEvent 动作码
_KEY_ACTION_DOWN = 0
_KEY_ACTION_UP = 1

# Pointer id（触摸用）
# scrcpy 中 SC_POINTER_ID_GENERIC_FINGER = UINT64_C(-2)，
# 作为有符号 int64 写入 q 格式即 -2，对应无符号 0xFFFFFFFFFFFFFFFE
_POINTER_ID_FINGER = -2

# 同一手势内相邻控制消息（如 DOWN→UP、按键 DOWN→UP）之间的最小间隔。
_MIN_GESTURE_INTERVAL = 0.01  # 10ms

# ── 探活（5.1）──
# 视频流正常时帧时间戳持续前进；静止画面下 scrcpy 不保证持续出帧，
# 因此时间戳超时后追加一次轻量 ADB 探活，避免把「画面没变」误判成「设备已断开」。
_ALIVE_FRAME_WINDOW = 1.5  # 帧时间戳超过该秒数视为可疑
_ALIVE_PROBE_TIMEOUT = 0.8  # ADB 探活超时（帧窗口 + 探活 < 3s 验收线）
_ALIVE_PROBE_CACHE = 1.0  # 探活结果缓存，避免状态轮询反复执行 adb shell


# ── 进程匹配（6.13 / R38）──
# 同时安装官服与渠道服时，`com.example.com.a` 是 `com.example.com.ab` 的
# 前缀，子串匹配会误判「已运行」。这里按 PS 输出的空白分词做整词匹配，
# 只允许包名后紧跟 ``:``（Android 远程服务子进程）或 ``/``（启动参数）。


def _ps_token_matches_package(token: str, package: str) -> bool:
    """判断单个 ps 字段是否就是目标包名（含 ``package:service`` 形式）。"""
    if token == package:
        return True
    if len(token) <= len(package) or not token.startswith(package):
        return False
    return token[len(package)] in ':/'


def _ps_output_has_package(ps_output: str, package: str) -> bool:
    """在 ps 输出中精确匹配包名，避免前缀包名（``a`` vs ``ab``）误判。"""
    if not ps_output or not package:
        return False
    return any(
        _ps_token_matches_package(token, package)
        for line in ps_output.splitlines()
        for token in line.split()
    )


def _ps_table_is_valid(ps_output: str) -> bool:
    """粗判输出是一张 ps 表（而不是 ``ps: unknown option`` 之类）。"""
    for line in ps_output.splitlines():
        fields = line.split()
        if len(fields) >= 2 and any(field.isdigit() for field in fields[:2]):
            return True
    return False


class ScrcpyController(AndroidController):
    """基于 scrcpy 协议的 Android 设备控制器。

    截图通过 scrcpy-server 提供的 H264 视频流解码获得（30+ fps）；
    触控（click/swipe/long_tap）、按键与文本输入通过 scrcpy 控制流实现，
    相比 ``adb shell input`` 显著降低延迟。仅应用管理类操作仍走 ADB。

    Parameters
    ----------
    serial:
        设备的 ADB serial 地址（如 ``"emulator-5554"``、``"127.0.0.1:16384"``）。
        为 None 时自动检测。
    config:
        :class:`~autowsgr.infra.config.EmulatorConfig` 实例。
    max_size:
        视频流最大尺寸（宽或高的上限，0 = 不限制）。
    bitrate:
        视频流码率（bps），默认 8Mbps。
    max_fps:
        视频流最大帧率（0 = 不限制）。
    screenshot_timeout:
        截图超时（秒），超过仍无帧时抛出异常。
    """

    def __init__(
        self,
        serial: str | None = None,
        config: EmulatorConfig | None = None,
        max_size: int = 0,
        bitrate: int = 8_000_000,
        max_fps: int = 0,
        screenshot_timeout: float = 10.0,
    ) -> None:
        self._serial = serial
        self._config = config
        self._max_size = max_size
        self._bitrate = bitrate
        self._max_fps = max_fps
        self._screenshot_timeout = screenshot_timeout

        self._device: AdbDevice | None = None
        self._resolution: tuple[int, int] = (0, 0)
        # 本次连接是否因 window_size() 拿不到尺寸而回退到默认 960x540。
        # 置位后保持到下一次 connect()/断开，供 /api/system/status 上报。
        self._resolution_fallback = False
        self._last_frame: np.ndarray | None = None
        # 最近一帧的解码时间（time.monotonic），供 is_alive() 判断视频流是否还活着。
        self._last_frame_at: float | None = None
        self._alive_probe_at = 0.0
        self._alive_probe_ok = False

        # scrcpy 连接状态
        self._alive = False
        self._closed = False  # disconnect() 之后置 True，禁止自动重连
        self._server_stream: AdbConnection | None = None
        self._video_socket: socket.socket | None = None
        self._control_socket: socket.socket | None = None
        self._decode_thread: threading.Thread | None = None
        self._frame_ready = threading.Event()  # 首帧就绪信号
        self._frame_lock = threading.Lock()
        self._reconnect_lock = threading.Lock()
        self._control_lock = threading.Lock()  # 控制流写串行化
        self._teardown_lock = threading.RLock()  # 资源回收串行化

    # ── 连接 ──

    def connect(self) -> DeviceInfo:
        self._closed = False
        self._frame_ready.clear()
        self._resolution_fallback = False
        self._last_frame_at = None
        self._alive_probe_at = 0.0
        self._alive_probe_ok = False

        # ── serial 解析 ──
        if self._serial:
            resolved = self._serial
        elif self._config is not None:
            resolved = resolve_serial(self._config)
        else:
            candidates = detect_emulators()
            if len(candidates) == 1:
                resolved = candidates[0].serial
                _log.info('[Emulator] 自动检测到唯一设备: {}', candidates[0].description)
            elif len(candidates) == 0:
                resolved = ''
            else:
                resolved = prompt_user_select(candidates)
        self._serial = resolved or None

        try:
            # ── 连接 adbutils 设备 ──
            self._connect_adb_device(resolved)
            assert self._device is not None

            # ── 获取初始分辨率 ──
            # adbutils 对无法解析的 `wm size` 输出（如空输出）会抛 AdbError，
            # 这里统一并入回退分支，否则「wm size 不可用」会直接导致连接失败。
            try:
                wsize = self._device.window_size()
            except Exception as exc:  # noqa: BLE001 - 任何查询失败都应回退默认分辨率
                _log.debug('[Emulator] 查询设备分辨率失败，将回退默认值: {}', exc)
                wsize = None
            if wsize:
                self._resolution = (wsize[0], wsize[1])
            else:
                self._resolution = (960, 540)  # fallback
                self._resolution_fallback = True
                _log.warning('[Emulator] 无法获取设备分辨率，使用默认值 960x540')

            # ── 部署并启动 scrcpy-server ──
            self._deploy_server()
            self._start_server()
            self._connect_video_socket()
            self._connect_control_socket()
            self._start_decode_thread()

            # ── 等待首帧 ──
            if not self._frame_ready.wait(timeout=self._screenshot_timeout):
                raise DeviceError(
                    f'scrcpy 视频流未能在 {self._screenshot_timeout}s 内产生首帧',
                    operation='connect',
                )

            _log.info(
                '[Emulator] 已连接设备 (scrcpy): {} ({}x{})',
                self._serial or 'auto',
                *self._resolution,
            )
            return DeviceInfo(
                serial=self._serial or 'auto',
                resolution=self._resolution,
            )
        except BaseException:
            # 连接中途失败同样要回收 socket / 解码线程 / 设备端进程，
            # 否则每次失败都会在模拟器里留下一个 scrcpy-server。
            _log.warning('[Emulator] 连接未完成，回收已建立的 scrcpy 资源')
            self._release()
            raise

    def _connect_adb_device(self, serial: str | None) -> None:
        """通过 adbutils 连接设备。"""
        import adbutils

        def _try_connect() -> None:
            if serial:
                # TCP 地址（如 127.0.0.1:16384）需先 adb connect
                if ':' in serial:
                    adbutils.adb.connect(serial, timeout=5.0)
                self._device = adbutils.adb.device(serial=serial)
            else:
                devices = adbutils.adb.device_list()
                if not devices:
                    raise DeviceError('未发现已连接的 ADB 设备', operation='connect')
                self._device = devices[0]
                self._serial = self._device.serial

        max_attempts = 3
        last_exc: Exception | None = None
        for attempt in range(1, max_attempts + 1):
            try:
                if attempt > 1:
                    _log.info('[Emulator] 重试连接 ({}/{})...', attempt, max_attempts)
                    self._restart_adb_server()
                    time.sleep(2.0)

                _try_connect()
            except Exception as exc:
                last_exc = exc
                _log.warning('[Emulator] 连接失败 (尝试 {}/{}): {}', attempt, max_attempts, exc)
            else:
                return

        raise DeviceError(
            f'连接设备失败（共尝试 {max_attempts} 次）: {self._serial}',
            operation='connect',
        ) from last_exc

    def _restart_adb_server(self) -> None:
        """重启 adb server。"""
        import subprocess

        try:
            adb = _find_adb()
            subprocess.run([adb, 'kill-server'], timeout=5, capture_output=True, check=False)  # noqa: S603
            time.sleep(1)
            subprocess.run([adb, 'start-server'], timeout=8, capture_output=True, check=False)  # noqa: S603
        except Exception as exc:
            _log.debug('[Emulator] 重启 adb server 失败: {}', exc)

    def _deploy_server(self) -> None:
        """推送 scrcpy-server.jar 到设备。"""
        if not _SCRCPY_SERVER_JAR.exists():
            raise DeviceError(
                f'找不到 scrcpy-server.jar: {_SCRCPY_SERVER_JAR}\n请确认 autowsgr 包数据完整',
                operation='deploy',
            )
        _log.debug('[Emulator] 推送 scrcpy-server.jar 到设备...')
        dev = self._require_device()
        dev.push(str(_SCRCPY_SERVER_JAR), _DEVICE_JAR_PATH)

    def _start_server(self) -> None:
        """在设备上启动 scrcpy-server 进程。"""
        cmd = [
            f'CLASSPATH={_DEVICE_JAR_PATH}',
            'app_process',
            '/',
            'com.genymobile.scrcpy.Server',
            _SCRCPY_SERVER_VERSION,
            'log_level=info',
            'tunnel_forward=true',
            'video=true',
            'audio=false',
            'control=true',
            f'max_size={self._max_size}',
            f'video_bit_rate={self._bitrate}',
            f'max_fps={self._max_fps}',
            'video_codec=h264',
            'send_device_meta=false',
            'send_frame_meta=false',
            'send_codec_meta=false',
            'send_dummy_byte=true',
        ]
        _log.debug('[Emulator] 启动 scrcpy-server: {}', ' '.join(cmd))
        dev = self._require_device()
        self._server_stream = dev.shell(cmd, stream=True)
        # 给 server 一点启动时间
        time.sleep(0.5)

    def _connect_video_socket(self) -> None:
        """连接 scrcpy 视频 socket。"""
        import adbutils

        dev = self._require_device()
        for _attempt in range(30):
            try:
                self._video_socket = dev.create_connection(
                    adbutils.Network.LOCAL_ABSTRACT,
                    'scrcpy',
                )
                break
            except Exception:
                time.sleep(0.1)
        else:
            raise DeviceError('无法连接 scrcpy-server 视频通道（3s 超时）', operation='connect')

        # 读取 dummy byte
        dummy = self._video_socket.recv(1)
        if not dummy:
            raise DeviceError('未收到 scrcpy dummy byte，连接可能已断开', operation='connect')
        _log.debug('[Emulator] scrcpy 视频通道已连接')

    def _connect_control_socket(self) -> None:
        """连接 scrcpy 控制通道（video 之后建立的第二个 socket）。

        scrcpy 2.7 中 ``send_dummy_byte=true`` 时 dummy byte 仅由第一个 socket
        （video）发送，控制 socket 无需读取 dummy byte。
        """
        import adbutils

        dev = self._require_device()
        for _attempt in range(30):
            try:
                self._control_socket = dev.create_connection(
                    adbutils.Network.LOCAL_ABSTRACT,
                    'scrcpy',
                )
                break
            except Exception:
                time.sleep(0.1)
        else:
            raise DeviceError('无法连接 scrcpy-server 控制通道（3s 超时）', operation='connect')

        # 禁用 Nagle，降低控制指令延迟
        try:
            self._control_socket.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
        except OSError:
            pass
        _log.debug('[Emulator] scrcpy 控制通道已连接')

    def _start_decode_thread(self) -> None:
        """启动后台 H264 解码线程。"""
        self._alive = True
        self._decode_thread = threading.Thread(
            target=self._stream_loop,
            name='scrcpy-decode',
            daemon=True,
        )
        self._decode_thread.start()

    def _stream_loop(self) -> None:
        """后台解码循环：接收 H264 流并解码为 numpy 帧。"""
        import av

        codec = av.CodecContext.create('h264', 'r')
        video_sock = self._video_socket
        assert video_sock is not None
        while self._alive:
            try:
                raw = video_sock.recv(0x10000)
                if not raw:
                    if self._alive:
                        _log.warning('[Emulator] scrcpy 视频流已断开')
                        self._alive = False
                    break

                for packet in codec.parse(raw):
                    for frame in codec.decode(packet):
                        rgb = frame.to_ndarray(format='rgb24')
                        h, w = rgb.shape[:2]

                        with self._frame_lock:
                            self._last_frame = rgb
                            self._last_frame_at = time.monotonic()
                            if self._resolution != (w, h):
                                _log.info(
                                    '[Emulator] scrcpy 视频分辨率: {}x{}',
                                    w,
                                    h,
                                )
                                self._resolution = (w, h)

                        if not self._frame_ready.is_set():
                            self._frame_ready.set()

            except BlockingIOError:
                time.sleep(0.01)
            except (ConnectionError, OSError) as exc:
                if self._alive:
                    _log.warning('[Emulator] scrcpy 视频流异常: {}', exc)
                    self._alive = False
                break

    def disconnect(self) -> None:
        """断开设备连接并回收全部 scrcpy 资源（幂等）。

        停止解码线程 → 关闭视频/控制 socket → 关闭 server 流 →
        回收设备端 scrcpy-server 进程与残留的 ``adb forward`` 规则，
        最后释放 ADB 设备引用。重复调用不会产生副作用。
        """
        serial = self._serial or 'auto'
        had_resources = (
            self._device is not None
            or self._alive
            or self._decode_thread is not None
            or self._video_socket is not None
            or self._control_socket is not None
        )
        self._release()
        if had_resources:
            _log.info('[Emulator] 已断开设备连接: {}', serial)
        else:
            _log.debug('[Emulator] 设备连接已处于断开状态: {}', serial)

    def _release(self) -> None:
        """回收 scrcpy 资源；保留 ``_serial`` 以便后续重连。"""
        with self._teardown_lock:
            device = self._device
            self._closed = True
            self._close_video_channel()
            if device is not None:
                self._kill_remote_server(device)
                self._remove_scrcpy_forwards(device.serial)
            self._device = None
            self._resolution = (0, 0)
            self._resolution_fallback = False
            self._last_frame = None
            self._last_frame_at = None
            self._alive_probe_at = 0.0
            self._alive_probe_ok = False

    @property
    def resolution(self) -> tuple[int, int]:
        return self._resolution

    @property
    def resolution_fallback(self) -> bool:
        """本次连接是否回退到了默认分辨率 960x540。"""
        return self._resolution_fallback

    def is_alive(self) -> bool:
        """设备是否仍可用（5.1 真实探活）。

        判据按代价从低到高排列，任一硬条件不满足即视为断开：

        1. 未处于已连接状态 / 解码线程已退出 / 视频或控制 socket 已关闭；
        2. 最近一帧的解码时间在 ``_ALIVE_FRAME_WINDOW`` 内；
        3. 帧时间戳超时（静止画面可能不出帧）时，追加一次带超时与缓存
           的 ADB 探活，避免把「画面没变」误判为「设备已断开」。

        本方法可在 HTTP 路由的工作线程中调用；探活耗时上界
        ``_ALIVE_FRAME_WINDOW`` + ``_ALIVE_PROBE_TIMEOUT``。
        """
        if not self._alive or self._closed:
            return False

        thread = self._decode_thread
        if thread is None or not thread.is_alive():
            return False

        video_sock = self._video_socket
        control_sock = self._control_socket
        if video_sock is None or control_sock is None:
            return False
        try:
            if video_sock.fileno() < 0 or control_sock.fileno() < 0:
                return False
        except OSError:
            return False

        with self._frame_lock:
            last_frame_at = self._last_frame_at
        if last_frame_at is None:
            return False

        now = time.monotonic()
        if now - last_frame_at <= _ALIVE_FRAME_WINDOW:
            return True

        if now - self._alive_probe_at <= _ALIVE_PROBE_CACHE:
            return self._alive_probe_ok

        self._alive_probe_at = now
        self._alive_probe_ok = self._probe_device()
        return self._alive_probe_ok

    def _probe_device(self) -> bool:
        """用一次轻量 ADB shell 确认设备进程仍可响应。"""
        device = self._device
        if device is None:
            return False
        try:
            output = str(
                device.shell(
                    'echo __autowsgr_alive',
                    timeout=_ALIVE_PROBE_TIMEOUT,
                )
                or ''
            )
        except Exception as exc:  # noqa: BLE001 - 探活失败统一视为断开
            _log.debug('[Emulator] 设备探活失败: {}', exc)
            return False
        if '__autowsgr_alive' in output:
            return True
        _log.warning('[Emulator] 设备探活无响应: {!r}', output[:120])
        return False

    def _require_device(self) -> AdbDevice:
        """返回已连接的设备实例，未连接时抛出异常。"""
        if self._device is None:
            raise DeviceError('设备未连接，请先调用 connect()', operation='connect')
        return self._device

    def _close_video_channel(self) -> None:
        """关闭视频/控制通道与 server 流，并等待解码线程退出。"""
        # 先置停止标志：解码线程在本次 recv 返回后会自行退出，
        # 不会把主动断开误判为「视频流异常断开」。
        self._alive = False
        self._close_sockets()
        self._close_server_stream()
        self._join_decode_thread()
        self._frame_ready.clear()

    def _close_sockets(self) -> None:
        if self._control_socket is not None:
            try:
                self._control_socket.close()
            except Exception as exc:
                _log.debug('[Scrcpy] 关闭 control socket 失败: {}', exc)
            self._control_socket = None

        if self._video_socket is not None:
            try:
                self._video_socket.close()
            except Exception as exc:
                _log.debug('[Scrcpy] 关闭 video socket 失败: {}', exc)
            self._video_socket = None

    def _close_server_stream(self) -> None:
        if self._server_stream is not None:
            try:
                self._server_stream.close()
            except Exception as exc:
                _log.debug('[Scrcpy] 关闭 server stream 失败: {}', exc)
            self._server_stream = None

    def _join_decode_thread(self) -> None:
        thread = self._decode_thread
        self._decode_thread = None
        if thread is None or thread is threading.current_thread():
            return
        if thread.is_alive():
            thread.join(timeout=3.0)
            if thread.is_alive():
                _log.debug('[Scrcpy] 解码线程未在 3s 内退出')

    def _kill_remote_server(self, device: AdbDevice) -> None:
        """回收设备端残留的 scrcpy-server 进程。

        正常情况下 socket 关闭后 server 会自行退出；这里做兜底，
        避免异常退出后 ``com.genymobile.scrcpy.Server`` 在模拟器里堆积。
        ``pkill -f`` 直接匹配 ``/proc/<pid>/cmdline``，不受 ``ps`` 的
        NAME 列截断影响；``[s]`` 写法避免匹配到 pkill 自身。
        """
        try:
            output = str(
                device.shell("pkill -f '[s]crcpy'; echo __rc=$?", timeout=5.0) or ''
            )
        except Exception as exc:
            _log.debug('[Scrcpy] 清理设备端 scrcpy 进程失败: {}', exc)
            return

        if '__rc=0' in output:
            _log.debug('[Scrcpy] 已清理设备端残留 scrcpy 进程')
            return
        if '__rc=127' not in output:
            return  # pkill 可用，且已经没有残留进程

        # 设备缺少 pkill：退回 ps + kill
        pids = self._find_remote_scrcpy_pids(device)
        if not pids:
            return
        try:
            device.shell('kill -9 ' + ' '.join(pids), timeout=5.0)
            _log.debug('[Scrcpy] 已清理设备端 scrcpy 进程: {}', ' '.join(pids))
        except Exception as exc:
            _log.debug('[Scrcpy] 清理设备端 scrcpy 进程失败: {}', exc)

    def _find_remote_scrcpy_pids(self, device: AdbDevice) -> list[str]:
        """查询设备端 scrcpy 进程 PID（``ps -A`` 的 NAME 列会被截断）。"""
        for cmd, pid_index in (('ps -A -o PID,ARGS', 0), ('ps -A', 1)):
            try:
                output = str(device.shell(cmd, timeout=5.0) or '')
            except Exception as exc:
                _log.debug('[Scrcpy] 查询设备进程失败: {}', exc)
                return []
            pids: list[str] = []
            for line in output.splitlines():
                if 'scrcpy' not in line:
                    continue
                fields = line.split()
                if len(fields) > pid_index and fields[pid_index].isdigit():
                    pids.append(fields[pid_index])
            if pids:
                return pids
        return []

    def _remove_scrcpy_forwards(self, serial: str | None) -> None:
        """移除本设备上指向 ``localabstract:scrcpy`` 的残留转发规则。

        当前实现直接走 ADB transport，不会创建 forward 规则；此处的清理
        只针对旧版本或异常退出留下的条目，避免端口被长期占用。
        """
        if not serial:
            return
        import subprocess

        try:
            adb = _find_adb()
            listed = subprocess.run(  # noqa: S603
                [adb, '-s', serial, 'forward', '--list'],
                timeout=5,
                capture_output=True,
                text=True,
                check=False,
            )
            for line in (listed.stdout or '').splitlines():
                fields = line.split()
                if len(fields) != 3 or fields[2] != 'localabstract:scrcpy':
                    continue
                subprocess.run(  # noqa: S603
                    [adb, '-s', serial, 'forward', '--remove', fields[1]],
                    timeout=5,
                    capture_output=True,
                    check=False,
                )
                _log.debug('[Scrcpy] 已移除残留 adb forward: {}', fields[1])
        except Exception as exc:
            _log.debug('[Scrcpy] 清理 adb forward 失败: {}', exc)

    def _reopen_stream(self) -> None:
        """在保持 ADB 设备连接的前提下重建 scrcpy 视频流与控制流。"""
        if self._closed or self._device is None:
            raise DeviceError('设备连接已断开，请重新连接', operation='stream')
        self._close_video_channel()
        self._last_frame = None
        self._last_frame_at = None
        self._alive_probe_at = 0.0
        self._alive_probe_ok = False
        try:
            self._deploy_server()
            self._start_server()
            self._connect_video_socket()
            self._connect_control_socket()
            self._start_decode_thread()

            if not self._frame_ready.wait(timeout=self._screenshot_timeout):
                raise DeviceError(
                    f'scrcpy 视频流重连失败：{self._screenshot_timeout}s 内无首帧',
                    operation='stream',
                )
        except BaseException:
            # 重连失败同样回收本次已经建立的通道与线程
            self._close_video_channel()
            raise

        _log.info('[Emulator] scrcpy 视频流已重连')

    def _ensure_stream_alive(self) -> None:
        """确保视频流可用，不可用时尝试一次重连。"""
        if self._closed or self._device is None:
            raise DeviceError('设备连接已断开，请重新连接', operation='stream')
        if self._alive:
            return

        with self._reconnect_lock:
            if self._alive:
                return

            _log.warning('[Emulator] 检测到视频流未运行，尝试自动重连')
            self._reopen_stream()

    # ── 控制流消息发送 ──

    def _require_control_socket(self) -> socket.socket:
        """返回控制 socket；视频流未就绪时先尝试恢复。"""
        self._ensure_stream_alive()
        if self._control_socket is None:
            raise DeviceError('scrcpy 控制通道未连接', operation='control')
        return self._control_socket

    def _send_control(self, data: bytes) -> None:
        """向控制 socket 串行写入一帧消息（线程安全）。"""
        sock = self._require_control_socket()
        with self._control_lock:
            try:
                sock.sendall(data)
            except (ConnectionError, OSError) as exc:
                _log.warning('[Emulator] 控制流发送失败，触发重连: {}', exc)
                self._alive = False
                self._ensure_stream_alive()
                sock = self._require_control_socket()
                sock.sendall(data)

    @staticmethod
    def _float_to_u16fp(value: float) -> int:
        """将 [0.0, 1.0] 压力值编码为 scrcpy u16 定点数。"""
        clamped = max(0.0, min(1.0, value))
        return round(clamped * 0xFFFF)

    @staticmethod
    def _float_to_i16fp(value: float) -> int:
        """将 [-1.0, 1.0] 滚动量编码为 scrcpy i16 定点数。"""
        clamped = max(-1.0, min(1.0, value))
        return round(clamped * 0x7FFF)

    def _to_absolute(self, x: float, y: float) -> tuple[int, int]:
        """将相对坐标 [0.0, 1.0] 转换为设备像素坐标。"""
        w, h = self._resolution
        return int(x * w), int(y * h)

    def _inject_touch(
        self,
        action: int,
        x: float,
        y: float,
        pressure: float = 1.0,
        pointer_id: int = _POINTER_ID_FINGER,
    ) -> None:
        """发送 INJECT_TOUCH_EVENT 控制消息（scrcpy 2.7，32 字节）。

        布局：type(1) | action(1) | pointer_id(8) | x(4) | y(4)
              | width(2) | height(2) | pressure(2) | action_button(4) | buttons(4)
        """
        w, h = self._resolution
        px, py = self._to_absolute(x, y)
        u16_pressure = self._float_to_u16fp(pressure)
        data = struct.pack(
            '>BBqIIHHHII',
            _TYPE_INJECT_TOUCH_EVENT,
            action,
            pointer_id,
            px,
            py,
            w,
            h,
            u16_pressure,
            0,  # action_button（触摸事件为 0）
            0,  # buttons（触摸事件为 0）
        )
        # struct '>BBqIIHHHII' = 1+1+8+4+4+2+2+2+4+4 = 32 字节
        self._send_control(data)

    def _inject_keycode(self, key_code: int, action: int = _KEY_ACTION_UP) -> None:
        """发送 INJECT_KEYCODE 控制消息（scrcpy 2.7，14 字节）。

        布局：type(1) | action(1) | keycode(4) | repeat(4) | metastate(4)
        """
        data = struct.pack(
            '>BBIII',
            _TYPE_INJECT_KEYCODE,
            action,
            key_code,
            0,  # repeat
            0,  # metastate
        )
        self._send_control(data)

    def _inject_scroll(
        self,
        x: float,
        y: float,
        *,
        horizontal: float,
        vertical: float,
    ) -> None:
        """发送 INJECT_SCROLL_EVENT 控制消息（scrcpy 2.7，21 字节）。"""
        width, height = self._resolution
        px, py = self._to_absolute(x, y)
        data = struct.pack(
            '>BIIHHhhI',
            _TYPE_INJECT_SCROLL_EVENT,
            px,
            py,
            width,
            height,
            self._float_to_i16fp(horizontal),
            self._float_to_i16fp(vertical),
            0,
        )
        self._send_control(data)

    def _inject_text(self, content: str) -> None:
        """发送 INJECT_TEXT 控制消息（scrcpy 2.7）。

        布局：type(1) | length(4) | utf8_bytes
        最大长度 300 字节。

        注意：INJECT_TEXT 通过 InputConnection.commitText 注入，
        仅对 ASCII/拉丁字符可靠；中文等多字节字符请使用 :meth:`_set_clipboard`。
        """
        raw = content.encode('utf-8')[:300]
        data = struct.pack('>BI', _TYPE_INJECT_TEXT, len(raw)) + raw
        self._send_control(data)

    def _set_clipboard(self, content: str, paste: bool = True) -> None:
        """发送 SET_CLIPBOARD 控制消息（scrcpy 2.7）。

        布局：type(1) | sequence(8) | paste(1) | length(4) | utf8_bytes

        ``paste=True`` 时，server 在设置剪贴板后会自动注入
        ``KEYCODE_PASTE``（Android ≥ 7），实现立即粘贴。
        该路径通过系统剪贴板 + 粘贴键工作，可正确输入中文等
        INJECT_TEXT 无法处理的字符。

        Parameters
        ----------
        content:
            要输入的文本（UTF-8，最长 262130 字节）。
        paste:
            是否在设置剪贴板后立即粘贴。
        """
        raw = content.encode('utf-8')[:_CLIPBOARD_TEXT_MAX_LENGTH]
        # sequence=0 表示 SEQUENCE_INVALID，不请求 ack
        data = struct.pack('>BQBI', _TYPE_SET_CLIPBOARD, 0, 1 if paste else 0, len(raw)) + raw
        self._send_control(data)

    # ── 截图 ──

    def screenshot(self) -> np.ndarray:
        self._ensure_stream_alive()

        start = time.monotonic()
        black_since: float | None = None
        while True:
            with self._frame_lock:
                frame = self._last_frame

            if frame is not None:
                if frame.size == 0:
                    raise DeviceError('截图返回空帧', operation='screenshot')
                if not frame.any():
                    # 全黑帧通常来自解码器/连接异常，不是可识别画面。
                    # 给短暂转场一个窗口，持续超过 screenshot_timeout 才判设备故障。
                    if not self._alive:
                        self._ensure_stream_alive()
                        black_since = None
                        start = time.monotonic()
                        continue
                    now = time.monotonic()
                    if black_since is None:
                        black_since = now
                        _log.warning('[Emulator] 截图为全黑，等待有效帧...')
                    elif now - black_since > self._screenshot_timeout:
                        raise DeviceError(
                            f'截图连续全黑 {self._screenshot_timeout}s，'
                            '设备可能黑屏或视频流已断',
                            operation='screenshot',
                        )
                    time.sleep(0.01)
                    continue

                elapsed = time.monotonic() - start
                h, w = frame.shape[:2]
                _log.trace(
                    '[Emulator] 截图完成 {}x{} 耗时={:.3f}s',
                    w,
                    h,
                    elapsed,
                )
                return frame

            if not self._alive:
                self._ensure_stream_alive()
                start = time.monotonic()
                continue

            if time.monotonic() - start > self._screenshot_timeout:
                raise DeviceError(
                    f'截图超时 ({self._screenshot_timeout}s)，scrcpy 视频流无数据',
                    operation='screenshot',
                )
            time.sleep(0.01)

    # ── 触控 ──
    # 引入一个开关，当参数为：click(x, y, delay=False) 时关闭延迟，该方法默认打开全局延迟，全局延迟可以在 config.py 内设置
    def click(self, x: float, y: float, *, delay: bool = True) -> None:
        w, h = self._resolution
        px, py = self._to_absolute(x, y)
        _log.debug(
            '[Emulator] click({:.3f}, {:.3f}) → pixel({}, {})  res={}x{}  {}',
            x,
            y,
            px,
            py,
            w,
            h,
            caller_info(),
        )
        self._inject_touch(_ACTION_DOWN, x, y, pressure=1.0)
        time.sleep(_MIN_GESTURE_INTERVAL)  # DOWN/UP 间留出最小间隔，防止游戏来不及处理
        self._inject_touch(_ACTION_UP, x, y, pressure=0.0)

        if delay:  # True 才走延迟
            time.sleep(operation_delay())

    def swipe(
        self,
        x1: float,
        y1: float,
        x2: float,
        y2: float,
        duration: float = 0.5,
        *,
        delay: bool = True,
    ) -> None:
        px1, py1 = self._to_absolute(x1, y1)
        px2, py2 = self._to_absolute(x2, y2)
        ms = int(duration * 1000)
        _log.debug(
            '[Emulator] swipe({:.3f},{:.3f}→{:.3f},{:.3f}) → pixel({},{}→{},{}) {}ms  {}',
            x1,
            y1,
            x2,
            y2,
            px1,
            py1,
            px2,
            py2,
            ms,
            caller_info(),
        )
        # 按下
        self._inject_touch(_ACTION_DOWN, x1, y1, pressure=1.0)
        time.sleep(_MIN_GESTURE_INTERVAL)  # DOWN 后留出最小间隔，再开始 MOVE 插值
        # 在 duration 内插值若干 MOVE 事件，保证流畅滑动
        steps = max(1, ms // 16)  # ~60fps，每步约 16ms
        step_ms = ms / steps
        for i in range(1, steps + 1):
            t = i / steps
            cx = x1 + (x2 - x1) * t
            cy = y1 + (y2 - y1) * t
            self._inject_touch(_ACTION_MOVE, cx, cy, pressure=1.0)
            # 每步之间的间隔就是 swipe 本身的节奏（约 16ms/步），
            # 已经足够避免连续发送过快；max() 仅在极短 duration 下兜底。
            time.sleep(max(step_ms / 1000.0, _MIN_GESTURE_INTERVAL))
        # 抬起
        self._inject_touch(_ACTION_UP, x2, y2, pressure=0.0)

        # 增加延迟，改动同 click_delay
        if delay:  # True 才走延迟
            time.sleep(operation_delay())

    def scroll(
        self,
        x: float,
        y: float,
        *,
        horizontal: float = 0.0,
        vertical: float = 0.0,
        delay: bool = True,
    ) -> None:
        _log.trace(
            '[Emulator] scroll({:.3f}, {:.3f}, h={:.3f}, v={:.3f})  {}',
            x,
            y,
            horizontal,
            vertical,
            caller_info(),
        )
        self._inject_scroll(x, y, horizontal=horizontal, vertical=vertical)
        if delay:
            time.sleep(operation_delay())

    def long_tap(self, x: float, y: float, duration: float = 1.0) -> None:
        px, py = self._to_absolute(x, y)
        ms = int(duration * 1000)
        _log.debug(
            '[Emulator] long_tap({:.3f}, {:.3f}) → pixel({},{}) {}ms  {}',
            x,
            y,
            px,
            py,
            ms,
            caller_info(),
        )
        # 按下后保持不动，再抬起（与 input swipe 同点等价）
        self._inject_touch(_ACTION_DOWN, x, y, pressure=1.0)
        time.sleep(duration)
        self._inject_touch(_ACTION_UP, x, y, pressure=0.0)

    # ── 按键 ──
    def key_event(self, key_code: int, *, delay: bool = True) -> None:
        _log.debug('[Emulator] key_event({})  {}', key_code, caller_info())
        # 发送 DOWN + UP 完成一次按键
        self._inject_keycode(key_code, action=_KEY_ACTION_DOWN)
        time.sleep(_MIN_GESTURE_INTERVAL)  # DOWN/UP 间留出最小间隔
        self._inject_keycode(key_code, action=_KEY_ACTION_UP)

        # 增加延迟，改动同 click_delay
        if delay:  # True 才走延迟
            time.sleep(operation_delay())

    def text(self, content: str, *, delay: bool = True) -> None:
        _log.debug("[Emulator] text('{}')  {}", content, caller_info())
        if content.isascii():
            # 纯 ASCII/拉丁字符走 INJECT_TEXT（延迟更低）
            self._inject_text(content)
        else:
            # 含中文等多字节字符 → SET_CLIPBOARD + paste（Android ≥ 7）
            self._set_clipboard(content, paste=True)

        # 增加延迟，改动同 click_delay
        if delay:  # True 才走延迟
            time.sleep(operation_delay())

    # ── 应用管理 ──

    def start_app(self, package: str, *, delay: bool = True) -> None:
        dev = self._require_device()
        _log.info('[Emulator] 启动应用: {}  {}', package, caller_info())
        dev.app_start(package)

        # 增加延迟，改动同 click_delay
        if delay:  # True 才走延迟
            time.sleep(operation_delay())

    def stop_app(self, package: str, *, delay: bool = True) -> None:
        dev = self._require_device()
        _log.info('[Emulator] 停止应用: {}  {}', package, caller_info())
        dev.app_stop(package)

        # 增加延迟，改动同 click_delay
        if delay:  # True 才走延迟
            time.sleep(operation_delay())

    def is_app_running(self, package: str) -> bool:
        package = (package or '').strip()
        if not package:
            return False
        try:
            dev = self._require_device()
            # 优先让设备只输出 PID,ARGS：`ps -A` 的 NAME 列可能被截断，
            # 而 ARGS 含完整包名。老设备不支持 -o 时退回完整 ps -A。
            ps_output = str(dev.shell('ps -A -o PID,ARGS') or '')
            if not _ps_table_is_valid(ps_output):
                ps_output = str(dev.shell('ps -A') or '')
        except Exception as exc:
            _log.debug(
                "[Emulator] is_app_running('{}') → False (设备异常: {})  {}",
                package,
                exc,
                caller_info(),
            )
            return False
        running = _ps_output_has_package(ps_output, package)
        _log.debug("[Emulator] is_app_running('{}') → {}  {}", package, running, caller_info())
        return running

    # ── Shell ──

    def shell(self, cmd: str) -> str:
        dev = self._require_device()
        result = dev.shell(cmd)
        if not isinstance(result, str):
            return str(result)
        return result
